// @vitest-environment node
import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { SUPPRESS_MODES } from './anonymity';
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore — generated by scripts/build-wasm.sh (wasm-bindgen)
import { initSync, suppress_mode_vocabulary } from '../wasm-pkg/anonymiser_wasm';

describe('SUPPRESS_MODES', () => {
    it('equals the wasm suppress_mode_vocabulary(), in order', () => {
        const dir = new URL('../wasm-pkg/', import.meta.url);
        initSync({ module: readFileSync(new URL('anonymiser_wasm_bg.wasm', dir)) });
        expect([...SUPPRESS_MODES]).toEqual(suppress_mode_vocabulary());
    });
});

describe('anonymity JSON shapes', () => {
    it('match the interfaces in anonymity.ts', async () => {
        const { realWasm } = await import('../lib/table/test-wasm');
        const w = realWasm();
        const rows = JSON.stringify([['a'], ['a'], ['b']]);
        const report = JSON.parse(w.k_anonymity_measure(rows, '[0]', 2));
        expect(Object.keys(report).sort()).toEqual(
            ['groups', 'k', 'min_group', 'per_column', 'rows', 'rows_below_k', 'satisfied'].sort()
        );
        expect(Object.keys(report.per_column[0]).sort()).toEqual(
            ['column', 'min_group_without', 'rows_below_k_without'].sort()
        );
        const out = JSON.parse(w.k_anonymity_suppress(rows, '[0]', 2, 'cells'));
        expect(Object.keys(out).sort()).toEqual(['rows', 'suppression']);
        expect(Object.keys(out.suppression).sort()).toEqual(
            [
                'cells_suppressed', 'groups_after', 'groups_before', 'k', 'min_group_after',
                'min_group_before', 'mode', 'rows_dropped', 'rows_in', 'rows_suppressed',
            ].sort()
        );
    });
});
